// ================================================================ deck 1 visuals: complex numbers and their algebra
const numberSystems = flow('LR', [['n', 'Natural numbers'], ['z', 'Integers'], ['q', 'Rational numbers'], ['r', 'Real numbers'], ['c', 'Complex numbers']], [['n', 'z'], ['z', 'q'], ['q', 'r'], ['r', 'c']], 'Flow diagram of the number systems, each larger than the last: natural numbers, integers, rational numbers, real numbers and finally complex numbers.', 'Each new set of numbers solves equations the previous one could not.');
const pNoRoot = plotF({ x: [-4, 4], y: [-1, 10], fns: [{ expr: 'x^2 + 1', label: '$y = x^2 + 1$' }], pts: [[0, 1, '(0, 1)'], [2, 5, '(2, 5)'], [-2, 5, '(−2, 5)']] }, 'The parabola y equal x squared plus 1, opening upward with its lowest point at (0, 1). It stays above the x-axis everywhere, so it never meets the axis: the equation x squared plus 1 equal 0 has no real root.', r`$x^2 + 1 = 0$ has no real root: the parabola never touches the $x$-axis.`);
must([-4, -2, -1, 0, 1, 2, 4].every((x) => x * x + 1 >= 1), 'x^2 + 1 >= 1');
