const defTable = table(['Complex number $z$', r`$\mathrm{Re}(z)$`, r`$\mathrm{Im}(z)$`, 'Kind'], defZs.map((z) => [tz(z), `$${z.re.n}$`, `$${z.im.n}$`, kind(z)]), 'Table of four complex numbers with their real and imaginary parts: 7 minus 5 i has real part 7 and imaginary part minus 5; minus 2 plus i has parts minus 2 and 1; 6 is real with imaginary part 0; minus 9 i is purely imaginary with real part 0.', r`$z = a + bi$: real part $a$, imaginary part $b$ (a real number, not $bi$).`);
const powVals = range(1, 8).map((n) => ctex(cpow(I, n)));
must(powVals.join() === 'i,-1,-i,1,i,-1,-i,1', 'powers of i');
const powTable = table(['$n$', ...range(1, 8).map((n) => `$${n}$`)], [['$i^n$', ...powVals.map((v) => `$${v}$`)]], 'Table of the powers of i from 1 to 8: i, minus 1, minus i, 1, then the same four values again, so the powers repeat in a cycle of length four.', 'The cycle $i, -1, -i, 1$ repeats every four powers.');
const remTable = table(['Remainder of $n \\div 4$', '$0$', '$1$', '$2$', '$3$'], [['$i^n$', ...range(0, 3).map((k) => `$${ctex(cpow(I, k))}$`)]], 'Table showing i to the power n by the remainder of n on division by 4: remainder 0 gives 1, remainder 1 gives i, remainder 2 gives minus 1, remainder 3 gives minus i.', r`$i^{n} = i^{r}$ where $r$ is the remainder of $n$ on division by $4$.`);
must(range(-30, 30).every((n) => ceq(cpow(I, n), cpow(I, ((n % 4) + 4) % 4))), 'i^n = i^(n mod 4) for n in -30..30');
const A1 = C(5, 2), B1 = C(3, -6);
const sumZ = cadd(A1, B1), difZ = csub(A1, B1);
must(ceq(sumZ, C(8, -4)) && ceq(difZ, C(2, 8)), 'sum and difference');
const addTable = table(['Operation', 'Working', 'Result'], [['$z_1 + z_2$', r`$(5 + 3) + (2 - 6)i$`, tz(sumZ)], ['$z_1 - z_2$', r`$(5 - 3) + (2 + 6)i$`, tz(difZ)]], 'Table for z one equal 5 plus 2 i and z two equal 3 minus 6 i: the sum adds real and imaginary parts to give 8 minus 4 i; the difference subtracts them to give 2 plus 8 i.', r`$z_1 = 5 + 2i$, $z_2 = 3 - 6i$: add or subtract part by part.`);
const M1 = C(4, 3), M2 = C(2, -5), mulZ = cmul(M1, M2);
must(ceq(mulZ, C(23, -14)) && 4 * 2 === 8 && 4 * -5 === -20 && 3 * 2 === 6 && 3 * -5 === -15, '(4 + 3i)(2 - 5i)');
const mulTable = table(['Step', 'Working'], [['Expand', r`$(4 + 3i)(2 - 5i) = 8 - 20i + 6i - 15i^2$`], ['Replace $i^2$ by $-1$', r`$= 8 - 20i + 6i + 15$`], ['Collect', `$= ${ctex(mulZ)}$`]], 'Table showing the product of 4 plus 3 i and 2 minus 5 i in three steps: expand into four terms, replace i squared by minus 1, and collect real and imaginary parts to get 23 minus 14 i.', r`Multiply like brackets in algebra, then use $i^2 = -1$.`);
const W1a = C(4, -1), W1b = C(2, 5), W1c = C(3, 2), w1p = cmul(W1a, W1b), w1 = cadd(w1p, W1c);
must(ceq(w1p, C(13, 18)) && ceq(w1, C(16, 20)), 'WE1 numbers');
const we1Table = table(['Step', 'Working'], [['Product', `$(4 - i)(2 + 5i) = 8 + 20i - 2i - 5i^2 = ${ctex(w1p)}$`], ['Add $3 + 2i$', `$(${ctex(w1p)}) + (3 + 2i) = ${ctex(w1)}$`]], 'Table for the expression 4 minus i times 2 plus 5 i, plus 3 plus 2 i: the product is 13 plus 18 i and adding 3 plus 2 i gives 16 plus 20 i.', r`Product first, then the sum.`);
const conjZs = [C(6, -5), C(-2, 7), C(0, 4), C(9, 0)];
const conjRows = conjZs.map((z) => { const zb = cconj(z), s = cadd(z, zb), p = cmul(z, zb); must(s.im.n === 0n && p.im.n === 0n && ceq(p, C(cmod2(z))), 'conj row'); return [tz(z), tz(zb), tz(s), tz(p)]; });
const conjTable = table(['$z$', r`$\bar z$`, r`$z + \bar z$`, r`$z\bar z$`], conjRows, 'Table of four complex numbers with their conjugates, sums and products: for 6 minus 5 i the conjugate is 6 plus 5 i, the sum is 12 and the product is 61; every sum and every product is a real number.', r`$z + \bar z = 2\,\mathrm{Re}(z)$ and $z\bar z = a^2 + b^2$ are always real.`);
const dN = C(7, 4), dD = C(3, -2), dNum = cmul(dN, cconj(dD)), dQ = cdiv(dN, dD);
must(ceq(dNum, C(13, 26)) && cmod2(dD).n === 13n && ceq(dQ, C(1, 2)) && ceq(cmul(dQ, dD), dN), 'WE2 division');
const divTable = table(['Step', 'Working'], [['Conjugate of the divisor', r`$3 - 2i \to 3 + 2i$`], ['Numerator', `$(7 + 4i)(3 + 2i) = 21 + 14i + 12i + 8i^2 = ${ctex(dNum)}$`], ['Denominator', r`$(3 - 2i)(3 + 2i) = 9 + 4 = 13$`], ['Quotient', `$\\dfrac{${ctex(dNum)}}{13} = ${ctex(dQ)}$`], ['Check', `$(${ctex(dQ)})(3 - 2i) = 7 + 4i$`]], 'Table dividing 7 plus 4 i by 3 minus 2 i: multiply top and bottom by 3 plus 2 i, the numerator becomes 13 plus 26 i, the denominator becomes 13, the quotient is 1 plus 2 i and multiplying back gives 7 plus 4 i.', r`Rationalise the denominator with the conjugate.`);
const divRule = table(['Step', 'Rule'], [['1', r`Conjugate of the divisor: $c + di \to c - di$`], ['2', 'Multiply the top and the bottom by it'], ['3', r`Denominator: $(c + di)(c - di) = c^2 + d^2$, a real number`], ['4', 'Expand the top, then split into real and imaginary parts']], 'Table of the four steps of complex division: take the conjugate of the divisor, multiply top and bottom by it, note that the new denominator is the real number c squared plus d squared, then expand the numerator and split into real and imaginary parts.', 'Division is rationalising with the conjugate.');
const eqSol = solveInts((x, y) => ceq(C(2 * x - y, x + 3 * y), C(3, 5)));
must(eqSol.length === 1 && eqSol[0].join() === '2,1', 'WE3 x = 2, y = 1');
const eqTable = table(['Step', 'Working'], [['Real parts equal', r`$2x - y = 3$`], ['Imaginary parts equal', r`$x + 3y = 5$`], ['Solve', r`$y = 2x - 3$, so $x + 6x - 9 = 5$: $x = 2$, $y = 1$`], ['Check', `$(2\\cdot 2 - 1) + i(2 + 3\\cdot 1) = ${ctex(C(3, 5))}$`]], 'Table solving the equation 2x minus y plus i times x plus 3y equal 3 plus 5 i: equate real parts and imaginary parts to get two linear equations, solve to find x equal 2 and y equal 1, and check.', r`$a + ib = c + id \iff a = c$ and $b = d$.`);
const eqRule = table(['Statement', 'Meaning'], [[r`$a + ib = c + id$`, r`$a = c$ **and** $b = d$`], [r`$x + 4i = 9 + yi$`, r`$x = 9$ and $y = 4$`], [r`$a + ib = 0$`, r`$a = 0$ and $b = 0$`]], 'Table of the equality rule for complex numbers: two complex numbers are equal exactly when their real parts are equal and their imaginary parts are equal, with two examples.', 'Compare parts, never the whole numbers.');
const summary1 = flow('LR', [['i', r`$i^2 = -1$; powers repeat every $4$`], ['a', 'Add, subtract, multiply like brackets'], ['c', r`Conjugate $\bar z$ makes $z\bar z$ real`], ['d', 'Divide with the conjugate; equal parts']], [['i', 'a'], ['a', 'c'], ['c', 'd']], 'Summary flow: the imaginary unit squares to minus 1 and its powers repeat; complex numbers add, subtract and multiply like brackets; the conjugate makes a product real; division uses the conjugate and equality compares parts.', 'Algebra of complex numbers in four steps.');

// ================================================================ deck 2 visuals: Argand plane, modulus, polar form, quadratics
const qZs = [C(3, 2), C(-2, 3), C(-3, -1), C(2, -3)];
const pPlane = argand({ x: [-5, 5], y: [-5, 5], pts: qZs.map((z, k) => ({ z, label: `$${ctex(z)}$`, vec: true, vecLabel: `arrow from the origin to the point ${k + 1}` })) }, 'The Argand plane with four points, one in each quadrant: 3 plus 2 i in the first, minus 2 plus 3 i in the second, minus 3 minus i in the third and 2 minus 3 i in the fourth, each joined to the origin. The real part is read along the horizontal axis and the imaginary part along the vertical axis.', r`Each $a + bi$ is the point $(a, b)$: real part across, imaginary part up.`);
