const pRing = argand({ x: [-7, 7], y: [-7, 7], pts: ringPts.map((z, k) => ({ z, label: `$${ctex(z)}$`, curve: true, ...(k === 0 ? { vec: true, vecLabel: 'radius to 3 + 4i, of length 5' } : {}) })), fns: [{ expr: 'sqrt(25 - x^2)', domain: [-5, 5], label: r`$|z| = 5$` }, { expr: '-sqrt(25 - x^2)', domain: [-5, 5] }] }, 'The Argand plane with the circle of radius 5 about the origin. Six marked points lie on it: 3 plus 4 i, minus 3 plus 4 i, minus 4 minus 3 i, 4 minus 3 i, 5 i and minus 5 i. The radius to 3 plus 4 i has length 5.', r`All points with $|z| = 5$ lie on one circle about the origin.`);
const P1 = C(2, 1), P2 = C(3, -2), pm1 = cmod(P1), pm2 = cmod(P2), pp = cmul(P1, P2), ppm = cmod(pp), pq = cdiv(P1, P2), pqm = cmod(pq);
must(ceq(pp, C(8, -1)) && ppm.tex === '\\sqrt{65}' && near(ppm.num, pm1.num * pm2.num) && near(pqm.num, pm1.num / pm2.num) && near(pqm.num, Math.sqrt(5 / 13)), 'modulus rules for 2 + i and 3 - 2i');
