const propsTable = table(['Rule', 'Left side', 'Right side'], [[r`$|z_1 z_2| = |z_1||z_2|$`, `$${ppm.tex}$`, `$${pm1.tex} \\times ${pm2.tex} = ${ppm.tex}$`], [r`$\left|\dfrac{z_1}{z_2}\right| = \dfrac{|z_1|}{|z_2|}$`, `$${pqm.tex}$`, `$\\dfrac{${pm1.tex}}{${pm2.tex}} \\approx ${pqm.num.toFixed(3)}$`], [r`$|\bar z| = |z|$`, `$${pm1.tex}$`, `$${pm1.tex}$`], [r`$z\bar z = |z|^2$`, `$${ctex(cmul(P1, cconj(P1)))}$`, `$${pm1.tex}^2 = 5$`]], 'Table checking four modulus rules for z one equal 2 plus i and z two equal 3 minus 2 i: the modulus of a product is the product of the moduli, the modulus of a quotient is the quotient of the moduli, a number and its conjugate have the same modulus, and z times its conjugate equals the modulus squared.', r`$z_1 = 2 + i$, $z_2 = 3 - 2i$.`);
const we1Mod = table(['Step', 'Working'], [['Product', `$(2 + i)(3 - 2i) = 6 - 4i + 3i - 2i^2 = ${ctex(pp)}$`], ['Modulus directly', `$|${ctex(pp)}| = \\sqrt{64 + 1} = ${ppm.tex}$`], ['By the rule', `$|2 + i|\\,|3 - 2i| = ${pm1.tex} \\times ${pm2.tex} = ${ppm.tex}$`]], 'Table finding the modulus of the product of 2 plus i and 3 minus 2 i two ways: the product is 8 minus i with modulus root 65, and the rule gives root 5 times root 13, which is also root 65.', 'Both routes agree.');
const T1 = C(2, 3), T2 = C(3, -1), Ts = cadd(T1, T2);
must(ceq(Ts, C(5, 2)), 'parallelogram sum');
const pPara = argand({ x: [-1, 7], y: [-3, 6], pts: [{ z: T1, label: '$z_1$', vec: true, vecLabel: 'arrow from the origin to z one' }, { z: T2, label: '$z_2$', vec: true, vecLabel: 'arrow from the origin to z two' }, { z: Ts, label: '$z_1 + z_2$', vec: true, vecLabel: 'arrow from the origin to the sum' }], lines: [[T1, Ts, 'side parallel to z two'], [T2, Ts, 'side parallel to z one']] }, 'The Argand plane with z one equal 2 plus 3 i, z two equal 3 minus i and their sum 5 plus 2 i. The origin, z one, the sum and z two are the corners of a parallelogram, and the diagonal from the origin is the sum.', r`$z_1 + z_2$ is the fourth corner of the parallelogram on $z_1$ and $z_2$.`);
const polFig = polarFig({ re: 1, im: Math.sqrt(3), argDeg: 60, s: 1.7, zLabel: r`$z$`, angleLabel: r`$60^\circ$`, alt: 'Axes with the point z equal 1 plus root 3 i in the first quadrant. The segment from the origin to z has length 2 and makes an angle of 60 degrees with the positive real axis; a dashed perpendicular goes down to the real axis.', caption: r`$z = 1 + \sqrt{3}\,i$: modulus $2$, argument $60^\circ$ (not to scale).` });
