const argTable = table(['$z$', 'Position', 'Principal argument'], argRows.map(([z, a]) => [tz(z), quadName(z), a]), 'Table of principal arguments: 1 plus i has 45 degrees, minus 1 plus i has 135, minus 1 minus i has minus 135, 1 minus i has minus 45; the positive real axis has 0, the positive imaginary axis 90, the negative real axis 180 and the negative imaginary axis minus 90 degrees.', r`The principal argument lies in $(-180^\circ, 180^\circ]$, measured anticlockwise from the positive real axis.`);
const we2z = [-1, -Math.sqrt(3)];
must(near(Math.hypot(...we2z), 2) && near((Math.atan2(we2z[1], we2z[0]) * 180) / Math.PI, -120) && fc.near(fc.polar(2, -120), we2z) && near(Math.atan(Math.sqrt(3)) * 180 / Math.PI, 60), 'WE2 polar form of -1 - i sqrt 3');
const we2Table = table(['Step', 'Working'], [['Modulus', r`$r = \sqrt{1 + 3} = 2$`], ['Quadrant', 'third (both parts negative)'], ['Related angle', r`$\tan\alpha = \sqrt{3}$, so $\alpha = 60^\circ$`], ['Argument', r`$\theta = -180^\circ + 60^\circ = -120^\circ$`], ['Polar form', r`$2\left(\cos(-120^\circ) + i\sin(-120^\circ)\right)$`]], 'Table converting minus 1 minus root 3 i to polar form: modulus 2, third quadrant, related angle 60 degrees, principal argument minus 120 degrees, so 2 times cosine of minus 120 degrees plus i sine of minus 120 degrees.', r`$z = -1 - \sqrt{3}\,i$.`);
